CREATE TABLE IF NOT EXISTS users ( id INTEGER PRIMARY KEY AUTOINCREMENT, discord_id TEXT NOT NULL UNIQUE, username TEXT NOT NULL, avatar TEXT, role TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, last_login INTEGER, mc_uuid TEXT, mc_name TEXT, xp INTEGER NOT NULL DEFAULT 0, play_minutes INTEGER NOT NULL DEFAULT 0, coins_spent INTEGER NOT NULL DEFAULT 0, coins_earned INTEGER NOT NULL DEFAULT 0, eq_frame TEXT, eq_hat TEXT, eq_color TEXT, permissions TEXT );
CREATE TABLE IF NOT EXISTS sessions ( token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS servers ( id TEXT PRIMARY KEY, ptero_uuid TEXT UNIQUE, name TEXT, game TEXT, address TEXT, port INTEGER, connect_override TEXT, description TEXT, description_es TEXT, mc_version TEXT, loader TEXT, loader_version TEXT, modpack TEXT, modpack_version TEXT, modpack_url TEXT, ram TEXT, join_steps TEXT, join_steps_es TEXT, hidden INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS ptero_servers ( uuid TEXT PRIMARY KEY, data TEXT NOT NULL, synced_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS posts ( id INTEGER PRIMARY KEY AUTOINCREMENT, server_id TEXT REFERENCES servers(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL, tag TEXT, event_at TEXT, pinned INTEGER NOT NULL DEFAULT 0, author_id INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_posts_server ON posts(server_id, created_at);
CREATE TABLE IF NOT EXISTS tasks ( id INTEGER PRIMARY KEY AUTOINCREMENT, server_id TEXT NOT NULL REFERENCES servers(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT, status TEXT NOT NULL DEFAULT 'open', created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_tasks_server ON tasks(server_id);
CREATE TABLE IF NOT EXISTS comments ( id INTEGER PRIMARY KEY AUTOINCREMENT, task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, body TEXT NOT NULL, created_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_comments_task ON comments(task_id, created_at);
INSERT OR IGNORE INTO servers (id, name, game, address, modpack, modpack_version, mc_version, loader, modpack_url, ram, join_steps, join_steps_es, hidden, sort_order, created_at, updated_at) VALUES ('skyfactory', 'SkyFactory', 'Minecraft', 'mc.moikas.cc', 'SkyFactory 5', NULL, '1.20.1', 'Forge', 'https://www.curseforge.com/minecraft/modpacks/skyfactory-5', '6–8 GB', '["Install the CurseForge app (or Prism Launcher).","Install the modpack at the exact version listed. A mismatched version will not connect.","Give Minecraft the recommended RAM in the launcher settings.","Launch the pack, click Multiplayer → Add Server, and enter the address."]', '["Instala la app de CurseForge (o Prism Launcher).","Instala el modpack en la versión exacta que aparece arriba. Si la versión no coincide, no vas a poder conectarte.","En la configuración del launcher, asígnale a Minecraft la RAM recomendada.","Abre el pack, entra a Multijugador → Agregar servidor y escribe la dirección."]', 0, 0, strftime('%s','now')*1000, strftime('%s','now')*1000);
INSERT INTO posts (server_id, title, body, tag, pinned, created_at, updated_at) SELECT NULL, 'New website is live', 'This is the new home for server info: which modpack to install, official announcements, events, and the tasks we''re working on together. Log in with Discord to join the discussion.', 'Announcement', 1, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE NOT EXISTS (SELECT 1 FROM posts);
CREATE TABLE IF NOT EXISTS chat_messages ( id INTEGER PRIMARY KEY AUTOINCREMENT, channel TEXT NOT NULL, user_id INTEGER REFERENCES users(id) ON DELETE SET NULL, body TEXT NOT NULL, deleted INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_chat_channel ON chat_messages(channel, id);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_mc_uuid ON users(mc_uuid);
CREATE TABLE IF NOT EXISTS mc_players ( uuid TEXT PRIMARY KEY, name TEXT NOT NULL, updated_at INTEGER NOT NULL );
CREATE INDEX IF NOT EXISTS idx_mc_players_name ON mc_players(name COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS mc_stats ( uuid TEXT NOT NULL, ptero_uuid TEXT NOT NULL, play_minutes INTEGER NOT NULL DEFAULT 0, stats TEXT, advancements TEXT, updated_at INTEGER NOT NULL, PRIMARY KEY (uuid, ptero_uuid) );
CREATE TABLE IF NOT EXISTS mc_links ( user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, mc_uuid TEXT NOT NULL, mc_name TEXT NOT NULL, code TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS quests ( id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, title_es TEXT, description TEXT, description_es TEXT, xp INTEGER NOT NULL, coins INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'manual', criteria_type TEXT, criteria_key TEXT, criteria_target INTEGER, server_id TEXT REFERENCES servers(id) ON DELETE SET NULL, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS quest_completions ( id INTEGER PRIMARY KEY AUTOINCREMENT, quest_id INTEGER NOT NULL REFERENCES quests(id) ON DELETE CASCADE, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, status TEXT NOT NULL DEFAULT 'pending', proof TEXT, review_note TEXT, reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, reviewed_at INTEGER, UNIQUE (quest_id, user_id) );
CREATE INDEX IF NOT EXISTS idx_completions_status ON quest_completions(status, created_at);
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Stone Age', 'Edad de piedra', 'Mine your first stone.', 'Mina tu primera piedra.', 50, 'auto', 'advancement', 'minecraft:story/mine_stone', NULL, 1, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE NOT EXISTS (SELECT 1 FROM quests);
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Diamonds!', '¡Diamantes!', 'Get the Diamonds! advancement.', 'Consigue el logro ¡Diamantes!.', 250, 'auto', 'advancement', 'minecraft:story/mine_diamond', NULL, 2, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 1;
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Miner', 'Minero', 'Mine 1,000 stone.', 'Mina 1,000 bloques de piedra.', 200, 'auto', 'stat', 'minecraft:mined/minecraft:stone', 1000, 3, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 2;
INSERT INTO quests (title, title_es, description, description_es, xp, kind, criteria_type, criteria_key, criteria_target, sort_order, created_at, updated_at) SELECT 'Free the End', 'Libera el End', 'Defeat the Ender Dragon.', 'Derrota al Ender Dragon.', 1000, 'auto', 'advancement', 'minecraft:end/kill_dragon', NULL, 4, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 3;
INSERT INTO quests (title, title_es, description, description_es, xp, kind, sort_order, created_at, updated_at) SELECT 'Show off your base', 'Presume tu base', 'Build a base and submit a screenshot link (Discord, Imgur…).', 'Construye una base y envía el enlace a una captura (Discord, Imgur…).', 150, 'manual', 5, strftime('%s','now')*1000, strftime('%s','now')*1000 WHERE (SELECT COUNT(*) FROM quests) = 4;
CREATE TABLE IF NOT EXISTS user_items ( user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, item_id TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (user_id, item_id) );
CREATE TABLE IF NOT EXISTS store_items ( id TEXT PRIMARY KEY, type TEXT NOT NULL, name TEXT NOT NULL, name_es TEXT, visual TEXT NOT NULL, price INTEGER, level INTEGER NOT NULL DEFAULT 0, reward_level INTEGER, active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL );
CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, value TEXT NOT NULL );
